export const TOTAL_WORDS = WORDS.length;
/** first frame at/after which word `s` (case-insensitive substring match, nth occurrence) is spoken */
export const wordAt = (s: string, nth = 1): number => {
  let n = 0;
  for (const x of WORDS) if (x.w.toLowerCase().includes(s.toLowerCase())) { n++; if (n === nth) return x.a; }
  return 0;
};
/** end frame of the nth match */
export const wordEnd = (s: string, nth = 1): number => {
  let n = 0;
  for (const x of WORDS) if (x.w.toLowerCase().includes(s.toLowerCase())) { n++; if (n === nth) return x.b; }
  return 0;
};
export const FRAME = (t: number) => Math.round(t * 30);

